import os,re,sys,yaml,collections
root='/Volumes/DAL/Zettelkasten/LLMeon'
notes={}
for d,_,fs in os.walk(root):
    if any(x in d for x in ('/.git','/.obsidian','/node_modules','/.trash')): continue
    for f in fs:
        if f.endswith('.md'):
            p=os.path.join(d,f)
            try: t=open(p,encoding='utf-8').read()
            except: continue
            notes[p]=t
def fm(t):
    m=re.match(r'^---\n(.*?)\n---\n?(.*)',t,re.S)
    if not m: return {},t
    try: return (yaml.safe_load(m.group(1)) or {}),m.group(2)
    except: return {'_bad':1},m.group(2)
inb=collections.Counter()
for p,t in notes.items():
    for l in re.findall(r'\[\[([^\]|#]+)',t):
        inb[l.strip()]+=1
rows=[]
for p,t in notes.items():
    f,b=fm(t)
    if str(f.get('type','')).lower()=='protocol' and '/10_System/templates/' not in p:
        name=os.path.basename(p)[:-3]
        heads=[h.strip().lower() for h in re.findall(r'^#{2,3} (.+)$',b,re.M)]
        pr=f.get('prodos') or {}
        rows.append(dict(path=os.path.relpath(p,root),name=name,status=f.get('status'),
          prefix=name.startswith('Protocol - '),
          kind=(pr.get('kind') if isinstance(pr,dict) else None),
          pp=bool(isinstance(pr,dict) and pr.get('protocol')),
          boxes=len(re.findall(r'^\s*- \[[ x]\]',b,re.M)),
          steps=bool([h for h in heads if 'step' in h or 'procedure' in h]),
          verif=bool([h for h in heads if 'verif' in h]),
          pre=bool([h for h in heads if 'precondition' in h or 'trigger' in h]),
          words=len(b.split()),inb=inb.get(name,0),ow=f.get('own_words'),
          conf=f.get('conformant')))
print(len(rows),'protocol notes')
rows.sort(key=lambda r:(r['path'].split('/')[0:2],r['name']))
for r in rows:
    print(f"{r['path'][:95]:95} pre={int(r['prefix'])} bx={r['boxes']:3} st={int(r['steps'])} vf={int(r['verif'])} pc={int(r['pp'])} w={r['words']:5} in={r['inb']:3} {r['status']} ow={r['ow']} cf={r['conf']}")
