(async()=>{
const L="30_Library/100_zettelkasten/";
const m=[
[L+"Protocol - Vague-to-Action.md","a task feels too heavy or undefined to start, or you notice you are avoiding it."],
[L+"Protocol - Big Rocks (Weekly Quadrant II Outcomes).md","the first working day of the week, when the Chief of Staff proposes the week's Big Rocks."],
[L+"Protocol - Co-Admin Onboarding (Zofja).md","onboarding Zofja as co-administrator of the household system."],
[L+"Protocol - Bessie Study Cadence & Neurodiverse Scaffolding.md","each day's Study Sprint, ahead of the 18:00 Audit Gate."],
[L+"Protocol - Third Urge Rule (Resilient Persistence).md","you feel the urge to quit or switch away from a difficult or uncomfortable task."],
[L+"Protocol - AWS HIE Jumpbox Access.md","you need shell access to the HIE jumpbox instance."],
[L+"Protocol - Azure Customer Preparation.md","preparing a customer's Azure tenant and subscription ahead of a FITFILE deployment."],
[L+"Protocol - Azure Jumpbox Preflight.md","before FITFILE deploys into a customer's Azure subscription."],
[L+"Protocol - HIE--NNUH Network Debugging.md","connectivity fails between clusters (for example EKS to AKS) or from the public internet to ingress."],
["Work/ops/Protocol - Azure Bastion Create Standard (LCRCA).md","you need to create a Standard Azure Bastion for the LCRCA environment."]];
const out=[];
for(const [p,t] of m){
 const f=app.vault.getAbstractFileByPath(p);
 if(!f){out.push("MISSING "+p);continue;}
 await app.vault.process(f,s=>{
  const mm=s.match(/^---\n[\s\S]*?\n---\n/);
  if(!mm){out.push("NOFM "+p);return s;}
  const head=mm[0], body=s.slice(head.length);
  if(/^\s*(>\s*)?\**Trigger\**:/i.test(body.slice(0,400))){out.push("HAS  "+p.split("/").pop());return s;}
  out.push("ADDED "+p.split("/").pop());
  return head+"\n> Trigger: "+t+"\n"+(body.startsWith("\n")?body:"\n"+body);
 });
}
const tu=app.vault.getAbstractFileByPath(L+"Protocol - Third Urge Rule (Resilient Persistence).md");
await app.vault.process(tu,s=>s.replace("## 🧩 The Protocol","## The Protocol").replace("## 🧠 The Logic","## The Logic"));
out.push("headings tidied");
return out.join("\n");
})()
